update public.notification_templates t
   set title = v.new_title,
       body = v.new_body,
       updated_at = now()
  from v
 where t.event_type = v.event_type
   and t.channel = v.channel
   and t.language_app_key = v.lk
   and t.ui_language = v.ui
   and t.title is not distinct from v.old_title
   and t.body = v.old_body;
